// SellThroughByDropRow aggregates a release/drop cohort (product.collection) into
// decision-grade totals, so tiny per-day/per-SKU samples roll up to a statistically
// meaningful drop-level view. sell_through_pct = units_sold / (units_sold +
// units_remaining) × 100 over the whole drop, computed lifetime (current state), not
// windowed — sell-through is inherently cumulative. Sorted by revenue desc.
export type SellThroughByDropRow = {
  collection: string | undefined;
  productCount: number | undefined;
  unitsSold: number | undefined;
  unitsRemaining: number | undefined;
  sellThroughPct: number | undefined;
  revenue: googletype_Decimal | undefined;
  unitsBought: number | undefined;
  grossMargin: googletype_Decimal | undefined;
  grossMarginPct: number | undefined;
  hasCost: boolean | undefined;
  daysTo50pct?: number;
  costedRevenue: googletype_Decimal | undefined;
};

// MarginByStyleRow rolls the per-SKU margin breakdown up to the STYLE (tech card) a product's
// primary_tech_card_id points at, so a style with several colourway SKUs is ONE row instead of
// many. tech_card_id = 0 is the "no style" bucket (products without a primary card). Revenue
// and COGS use the same order_factors apportionment as the product breakdowns; margins are N/A
// (has_cost=false) when the sold SKUs carry no cost.
export type MarginByStyleRow = {
  techCardId: number | undefined;
  styleNumber: string | undefined;
  name: string | undefined;
  revenue: googletype_Decimal | undefined;
  unitsSold: number | undefined;
  colorwayCount: number | undefined;
  unitCost: googletype_Decimal | undefined;
  revenueCost: googletype_Decimal | undefined;
  grossMargin: googletype_Decimal | undefined;
  grossMarginPct: number | undefined;
  hasCost: boolean | undefined;
};

// CogsStructureRow is one component of the cost of goods SOLD in the period, attributed from
// each product's cost_breakdown snapshot. The actual line COGS is split by the breakdown's
// component proportions, so components sum to the reported COGS; sold units with no breakdown
// (manual cost / pre-feature) collect in the "unattributed" component so coverage is visible.
export type CogsStructureRow = {
  component: string | undefined;
  amount: googletype_Decimal | undefined;
  pct: number | undefined;
};

// InventoryValuation is the money view of the warehouse: cost frozen in stock, how much is dead
// (unsold in the window), and damage/loss write-offs in the period. Stock is valued at the
// current plan cost_price (v1); products without a cost are counted as uncosted (value unknown),
// never as zero, so coverage is honest.
export type InventoryValuation = {
  totalStockValue: googletype_Decimal | undefined;
  totalOnHandUnits: number | undefined;
  costedOnHandUnits: number | undefined;
  uncostedStockUnits: number | undefined;
  uncostedStockProducts: number | undefined;
  coveragePct: number | undefined;
  topByValue: InventoryValuationRow[] | undefined;
  deadStock: InventoryValuationRow[] | undefined;
  writeOffsValue: googletype_Decimal | undefined;
  writeOffsUnits: number | undefined;
  // Raw-material warehouse (NF-09). Materials valued at moving-average unit cost, base EUR.
  rawMaterialsValue: googletype_Decimal | undefined;
  rawMaterialsCount: number | undefined;
  rawUncostedCount: number | undefined;
  wipValue: googletype_Decimal | undefined;
  writeoffsMaterialsValue: googletype_Decimal | undefined;
  topMaterialsByValue: MaterialValuationRow[] | undefined;
};

// InventoryValuationRow is one product's frozen stock value: on-hand units × current per-unit
// cost. sold_units is the product's net units sold in the window (0 ⇒ dead stock).
export type InventoryValuationRow = {
  productId: number | undefined;
  productName: string | undefined;
  onHand: number | undefined;
  unitCost: googletype_Decimal | undefined;
  value: googletype_Decimal | undefined;
  soldUnits: number | undefined;
};

// MaterialValuationRow is one raw-material line in the warehouse money view (NF-09).
export type MaterialValuationRow = {
  materialId: number | undefined;
  name: string | undefined;
  unit: string | undefined;
  onHand: googletype_Decimal | undefined;
  avgUnitCostBase: googletype_Decimal | undefined;
  value: googletype_Decimal | undefined;
};

// OrderValueBandRow is one fixed order-value bucket: how many orders and how much net revenue
// fall in [from, to) EUR. Bands are fixed (not quantile) so they are comparable across periods.
// Order value is net of VAT and after discounts/refunds — consistent with AOV, so band edges will
// not line up with on-site sticker prices.
export type OrderValueBandRow = {
  label: string | undefined;
  from: googletype_Decimal | undefined;
  to: googletype_Decimal | undefined;
  orders: number | undefined;
  revenue: googletype_Decimal | undefined;
  ordersSharePct: number | undefined;
  revenueSharePct: number | undefined;
  avgOrderValue: googletype_Decimal | undefined;
};

// DeliverySection reports fulfilment speed for orders PLACED in the period (a placed-cohort, so the
// average is not dragged by tails of earlier periods). Durations come from order_status_history
// timestamps; on-time compares delivered_at against shipment.estimated_arrival_date. Delivered is
// operator-flipped, so gate the delivered-based figures on delivered_coverage_pct / delivered_sample.
export type DeliverySection = {
  avgDaysPlacedToShipped: number | undefined;
  avgDaysShippedToDelivered: number | undefined;
  avgDaysPlacedToDelivered: number | undefined;
  medianDaysPlacedToDelivered: number | undefined;
  onTimeRatePct: number | undefined;
  onTimeSample: number | undefined;
  etaCoveragePct: number | undefined;
  deliveredCoveragePct: number | undefined;
  deliveredSample: number | undefined;
  shippedSample: number | undefined;
  avgDeliveryDaysByWeek: TimeSeriesPoint[] | undefined;
  caveat: string | undefined;
};

// RevenueForecast projects net revenue for the calendar month containing the period end. It blends a
// day-of-week run-rate (trailing 8 weeks) with a seasonal ratio-to-date from last year when that data
// exists. DB-only (no GA4). Directional at this data scale — read the low/high band, not the point.
export type RevenueForecast = {
  month: wellKnownTimestamp | undefined;
  mtdActual: googletype_Decimal | undefined;
  forecast: googletype_Decimal | undefined;
  forecastLow: googletype_Decimal | undefined;
  forecastHigh: googletype_Decimal | undefined;
  runRate: googletype_Decimal | undefined;
  method: string | undefined;
  elapsedDays: number | undefined;
  remainingDays: number | undefined;
  lastYearMonthTotal: googletype_Decimal | undefined;
  caveat: string | undefined;
};

// ProfitabilitySection is the self-contained "Profitability" tab (analytics-v2 task 07): the margin
// figures and their erosion (discounts), the acquisition-economics block (CPO / blended CAC / LTV /
// LTV·CAC), fulfilment cost per order, returns, and the operating-result roll-up — assembled from the
// SAME builders the dashboard uses so the shared figures tie out. CPO/CAC/LTV·CAC use manually-entered
// media spend (channel_spend): when none is entered has_spend=false and they are 0 (N/A, not "free").
// Cost/margin fields are stripped for accounts without costing:read; ltv (revenue-side) is kept.
export type ProfitabilitySection = {
  // --- margin and its erosion (assembly of existing figures) ---
  grossMargin: MetricWithComparison | undefined;
  grossMarginPct: MetricWithComparison | undefined;
  costCoveragePct: number | undefined;
  totalDiscount: MetricWithComparison | undefined;
  productSaleDiscount: MetricWithComparison | undefined;
  promoCodeDiscount: MetricWithComparison | undefined;
  discountRatePct: MetricWithComparison | undefined;
  contributionMargin: MetricWithComparison | undefined;
  // --- acquisition economics (new) ---
  cpo: MetricWithComparison | undefined;
  blendedCac: MetricWithComparison | undefined;
  hasSpend: boolean | undefined;
  ltv: googletype_Decimal | undefined;
  ltvCacRatio: number | undefined;
  fulfilmentCostPerOrder: MetricWithComparison | undefined;
  // --- returns and the bottom line ---
  refundRate: MetricWithComparison | undefined;
  totalRefunded: MetricWithComparison | undefined;
  opexTotal: googletype_Decimal | undefined;
  marketingSpend: googletype_Decimal | undefined;
  operatingResult: googletype_Decimal | undefined;
  opexCaveat: string | undefined;
  caveat: string | undefined;
};

export type GetDashboardRequest = {
  // Period spec, same grammar as GetMetrics (7d, 30d, 90d, today, WTD, MTD, QTD, YTD).
  period: string | undefined;
  // Optional window end (defaults to now). The period is measured back from here.
  endAt: wellKnownTimestamp | undefined;
  // Max rows per action list (top-by-margin, reorder, clear, drops). 0 = server default.
  limit: number | undefined;
  // Period-over-period comparison of the headline figures. NONE/UNSPECIFIED (default) = no
  // comparison; PREVIOUS_PERIOD = the same-length window immediately before; SAME_PERIOD_LAST_YEAR
  // = the same calendar dates a year earlier. When a real mode is set, the response carries `compare`.
  compareMode: CompareMode | undefined;
};

// DashboardAlert is a server-computed, threshold-driven alert. Rate-based alerts are gated on
// a minimum order count, so they never fire on a statistically meaningless sample.
export type DashboardAlert = {
  severity: AlertSeverity | undefined;
  code: string | undefined;
  title: string | undefined;
  detail: string | undefined;
};

export type GetDashboardResponse = {
  period: TimeRange | undefined;
  revenue: googletype_Decimal | undefined;
  orders: number | undefined;
  grossMargin: googletype_Decimal | undefined;
  grossMarginPct: number | undefined;
  // Contribution margin (gross_margin − shipping − payment_fees) = contribution to FIXED COSTS,
  // NOT profit. Fixed costs (salaries, rent, software, marketing, …) are excluded here; see
  // operating_result for the figure after them. Do not read "38% margin" as "38% profit" (task 22).
  contributionMargin: googletype_Decimal | undefined;
  costCoveragePct: number | undefined;
  caveat: string | undefined;
  uncostedProductIds: number[] | undefined;
  alerts: DashboardAlert[] | undefined;
  topByMargin: ProductMetric[] | undefined;
  reorder: InventoryHealthRow[] | undefined;
  clear: SlowMoverRow[] | undefined;
  drops: SellThroughByDropRow[] | undefined;
  // GA4-vs-DB revenue reconciliation (task 20 step 1): how much of the period's real (DB)
  // revenue the client-side GA4 tracking actually saw. A low figure means consent banners /
  // ad-blockers / bot filtering are eating attribution, so read ROAS as ≈ shown / coverage.
  ga4Revenue: googletype_Decimal | undefined;
  trackingCoveragePct: number | undefined;
  // Operating result (task 22): the honest total under contribution — an EBITDA-ish approximation.
  // operating_result = contribution_margin − opex_total − marketing_spend. opex_total is the
  // day-pro-rated fixed-cost journal for the period; marketing_spend is channel_spend for the
  // period (subtracted here, not in contribution). opex_caveat is set when no OPEX is recorded for
  // the period, so the operating result is read as incomplete.
  operatingResult: googletype_Decimal | undefined;
  opexTotal: googletype_Decimal | undefined;
  marketingSpend: googletype_Decimal | undefined;
  opexCaveat: string | undefined;
  // Period-over-period comparison of the six headline figures. Present only when the request set
  // compare_mode to a real mode. Every headline metric is higher-is-better, so a positive change
  // is always a good move (no per-field direction flag needed). The margin/contribution/operating
  // figures here (values AND change fields) are confidential and redacted for accounts without
  // costing:read, exactly like their top-level twins.
  compare: DashboardComparison | undefined;
};

// DashboardComparison is the prior-period snapshot of the dashboard headline figures plus the
// period-over-period change, so each headline tile can render "€42,300 ▲12% vs prev". *_change_pct
// is 100*(current−prior)/prior, left 0 when prior is 0 (no base). The gross-margin-% delta is a
// percentage-POINT change (change_pp), NOT a percent-of-a-percent. revenue and orders are public;
// the margin/contribution/operating figures and their change fields are confidential (redacted
// without costing:read).
export type DashboardComparison = {
  period: TimeRange | undefined;
  revenue: googletype_Decimal | undefined;
  revenueChangePct: number | undefined;
  orders: number | undefined;
  ordersChangePct: number | undefined;
  grossMargin: googletype_Decimal | undefined;
  grossMarginChangePct: number | undefined;
  grossMarginPct: number | undefined;
  grossMarginPctChangePp: number | undefined;
  contributionMargin: googletype_Decimal | undefined;
  contributionMarginChangePct: number | undefined;
  operatingResult: googletype_Decimal | undefined;
  operatingResultChangePct: number | undefined;
};

// AlertSettings are the operator-tunable thresholds behind the dashboard alerts.
export type AlertSettings = {
  coverageWarnPct: number | undefined;
  refundRateWarnPct: number | undefined;
  rateFloorN: number | undefined;
  contributionTrustPct: number | undefined;
  ga4CoverageWarnPct: number | undefined;
  productionRunStaleDays: number | undefined;
  acctPostingLagHours: number | undefined;
  // House gross-margin target, 0..100 — the default a style's costing measures itself against when
  // it sets no target of its own (common.TechCardCosting.target_margin_pct). Read back resolved on
  // TechCardCosting.effective_target_margin_pct, so the costing tab does not need this RPC.
  targetMarginPct: number | undefined;
};

