// WorkshopSettings is the singleton shop-floor configuration (workshop_settings, 0272).
export type WorkshopSettings = {
  // Usable length of the cutting/spreading table, in CENTIMETRES.
  // ABSENT means the workshop has not configured a table, and that is NOT the same as zero. A
  // consumer computing a length verdict must render "no verdict available" for an absent value —
  // comparing against 0 would tell a workshop that has merely not filled this in that every
  // раскладка it lays is too long, which is worse than saying nothing.
  cuttingTableLengthCm: googletype_Decimal | undefined;
  updatedBy: string | undefined;
  updatedAt: wellKnownTimestamp | undefined;
  // ПРИПУСК НА ШОВ ПО УМОЛЧАНИЮ, in centimetres — второй жилец дома настроек цеха (Ф2.5 → Ф3.2).
  // ABSENT = not configured, and a consumer must degrade to «no standard» rather than substitute
  // zero — the same law as the table length above. But UNLIKE the table length, ZERO IS LEGAL HERE
  // and means a specific thing: «our выкройки carry the cut line, no offset is needed». That is
  // exactly why 0272 chose a TYPED COLUMN PER SETTING over a shared key/value table: one CHECK
  // across all keys cannot express that difference, and here the two validators genuinely disagree
  // (the table length rejects 0, this accepts it).
  // A tech card may override it (common.TechCardInsert.required_seam_allowance_cm).
  defaultSeamAllowanceCm: googletype_Decimal | undefined;
  // BLOCKING MODE of the production-run readiness gate (Ф6.1/Ф6.9) — третий жилец дома настроек цеха.
  // ABSENT = not configured, and — UNLIKE every other tenant of this house — «not configured» here
  // has a DEFINED BEHAVIOUR: REPORT-ONLY MODE. The gate computes and shows everything and does not
  // refuse the creation of a run. There is no third state a command can be in, so «no verdict» is
  // not available to this setting the way it is to the table length.
  // Rolling the column out any other way would have stopped production outright: on the day Ф6 ships
  // not a single card carries a norm with recorded measurement conditions, so «no verdict ⇒ refuse»
  // would have refused everyone.
  // true is switched on ONLY after кампания Д3 (re-measuring the norms). The order is forced and
  // physically irreversible: directions (Д1) → re-measure after Ф3 ships (Д3) → blocking (Д4).
  runReadinessBlocking?: boolean;
  // ПРЕДЕЛ ВЫСОТЫ СТОПКИ, in CENTIMETRES — четвёртый жилец дома настроек цеха (Ф4.8), and the house
  // rule holds again after the one tenant that broke it: ABSENT = не настроено, and a consumer must
  // then say NOTHING about the height rather than compare against zero.
  // САНТИМЕТРЫ, А НЕ ЧИСЛО СЛОЁВ — the whole reason this is a shop setting and not a per-marker one:
  // 30 слоёв шифона это 2 см, 30 слоёв драпа — 30 см. What actually limits the лежание is the blade,
  // and a blade cuts a HEIGHT. Accepted band (0, 100]; the longest knives reach about 30 cm, so past
  // a hundred it is a unit mistake rather than a workshop.
  // ONE limit per shop (решение Р5), not one per fabric: пер-ножевые пределы are a refinement with
  // no data behind it today, and a column nothing can fill is not created. The article-side half of
  // the check is common.Material.fabric_thickness_mm; either one absent ⇒ UNKNOWN, and the screen
  // says which of the two is missing rather than printing a height nobody can trust.
  maxStackHeightCm: googletype_Decimal | undefined;
};

export type GetWorkshopSettingsRequest = {
};

export type GetWorkshopSettingsResponse = {
  settings: WorkshopSettings | undefined;
};

// UpdateWorkshopSettingsRequest is a PARTIAL update, and each setting is TRI-STATE:
// * ABSENT               — leave the stored value alone. This is the default for any client that
// does not know the setting exists, so a workshop screen shipped before a
// new tenant landed can never wipe it.
// * PRESENT, empty value — clear the setting back to "not configured". Needed for real: an
// operator who mistyped the table length must be able to return it to
// unknown, because a wrong number produces confident false verdicts while
// an unset one produces none.
// * PRESENT with a number — set it.
// NOTE for JSON/REST callers: protojson cannot tell `"cuttingTableLengthCm": null` from an absent
// field, so null also reads as "leave alone". To CLEAR a setting send the empty message —
// `{"cuttingTableLengthCm": {}}` — not null.
// A request that names no setting at all is rejected rather than executed: it would write nothing
// but still stamp updated_by/updated_at, putting a fake edit in the audit trail.
export type UpdateWorkshopSettingsRequest = {
  // Centimetres. Rejected with a field-tagged InvalidArgument outside the plausibility band
  // (entity.Min/MaxCuttingTableLengthCm): the single most likely operator mistake is typing METRES
  // into a field labelled centimetres, and "6" for a 6 m table would otherwise be accepted and then
  // declare every раскладка too long.
  cuttingTableLengthCm: googletype_Decimal | undefined;
  // Centimetres, 0..10. Zero is ACCEPTED (see WorkshopSettings.default_seam_allowance_cm) — send the
  // empty message to clear the setting instead. The ceiling is a unit check: the widest real
  // allowance is a 4-5 cm hem, so anything past 10 is millimetres typed into a centimetre field or a
  // stray zero.
  defaultSeamAllowanceCm: googletype_Decimal | undefined;
  // Ф6.9 — the blocking-mode switch. `optional` is MANDATORY here and is not decoration: without
  // presence, «did not send the field» and «turn it off» are the same bytes on the wire, and a stale
  // bundle saving the workshop screen would silently disable the gate. Exactly the price already
  // paid on fabric_direction.
  // Absent = leave alone. Present false = report-only. Present true = blocking. There is no
  // "clear it back to unset" for a bool, and none is needed: false and unset behave identically
  // (report-only), which is the whole point of the column's NULL having a defined behaviour.
  runReadinessBlocking?: boolean;
  // Ф4.8 — предел высоты стопки, CENTIMETRES, band (0, 100]. Zero is REJECTED rather than stored:
  // a limit of 0 cm would fail every настил ever laid, so «у нас нет предела» is expressed by
  // clearing the setting (send the empty message), which withholds the verdict instead of failing
  // it. Same floor argument as the table length, opposite to the seam allowance's legal zero.
  maxStackHeightCm: googletype_Decimal | undefined;
};

export type UpdateWorkshopSettingsResponse = {
  settings: WorkshopSettings | undefined;
};

