export type CreateTechCardRequest = {
  techCard: common_TechCardInsert | undefined;
};

export type common_TechCardInsert = {
  // identification (Sheet «Титул»)
  // Артикул. Required from the PROTO stage onward; OPTIONAL (empty) while stage == IDEA — an idea
  // is by definition pre-article (NF-03/B-2). Moving a card out of IDEA without a real style
  // number is rejected with InvalidArgument. A hand-typed override must set style_number_source =
  // MANUAL and pass the strict format validator; the global UNIQUE(style_number) index is the
  // authority on collisions (Q1). Use SuggestStyleNumber to get the server proposal.
  styleNumber: string | undefined;
  styleNumberSource: common_StyleNumberSource | undefined;
  name: string | undefined;
  brand: string | undefined;
  collection: string | undefined;
  categoryId: number | undefined;
  targetGender: common_GenderEnum | undefined;
  stage: common_TechCardStage | undefined;
  status: string | undefined;
  approvalState: common_TechCardApprovalState | undefined;
  // approved_by (36) removed (Q5): approval is the APPROVER role + a server-stamped journal event,
  // not a free-text name. version (10) / revision_date (11) removed (Q1): the card's version is the
  // sequence of named releases (Rev.N) + the auto-journal, not a free-text string. designer (14) /
  // constructor (15) / technologist (16) removed (Q5): roles are admin-account assignments now (see
  // the role-assignment RPCs). Migration 0223 drops all six retired columns from tech_card.
  releasedAt: wellKnownTimestamp | undefined;
  measurementUnit: common_TechCardMeasurementUnit | undefined;
  baseModelId: number | undefined;
  baseSampleSizeId: number | undefined;
  // construction description (lower block of Sheet «Титул») now lives in details[]; the
  // header targets / currency were removed (pricing is on costing, single brand policy).
  notes: string | undefined;
  // children (full-replace on update)
  sizeIds: number[] | undefined;
  // Sketch media split into two INDEPENDENT lists (replaces the single `media = 32`):
  // moodboard_media — mood / inspiration / reference / fabric-swatch photos (design intent)
  // technical_media — flat sketches used in construction (front / back / detail / lining / preview)
  // Construction consumes ONLY technical_media. Each item's `kind` sub-classifies within its
  // list. Both are full-replace on update. A callout pins onto ANY media_id on the card — moodboard
  // OR technical (the backend does not restrict the category), so at the idea stage a callout can pin
  // onto a moodboard/reference image before any technical sketch exists.
  moodboardMedia: common_TechCardMediaItem[] | undefined;
  technicalMedia: common_TechCardMediaItem[] | undefined;
  callouts: common_TechCardCallout[] | undefined;
  // materials (Phase 2): bill of materials (article catalog). Colourways are no longer style
  // children (R1 merge — a colourway is a product); their material recipe lives on the colourway via
  // ColorwayDevelopmentInsert.usages, keyed by an explicit colorway_id = product.id.
  // CONTRACT (nf05-01): downstream references into bom_items are POSITIONAL, by index, and every
  // write is a full replace (bom_items have no stable ids across a save). So when a BOM line is
  // removed or reordered, the client MUST renumber all downstream bom_item_index / fusing_bom_item_index
  // in the SAME payload (operations, pieces). An out-of-range index is rejected; an in-range-but-wrong
  // one is not — the server range-checks but cannot detect a wrong-but-valid index. Pieces address
  // their colourway by explicit colorway_id (not a positional index).
  bomItems: common_TechCardBomItem[] | undefined;
  // production (Phase 3): construction, operations, labels, packaging, costing.
  construction: common_TechCardConstruction | undefined;
  operations: common_TechCardOperation[] | undefined;
  labels: common_TechCardLabel[] | undefined;
  packaging: common_TechCardPackaging | undefined;
  costing: common_TechCardCosting | undefined;
  // hardening (Phase 3.5a)
  approvedAt: wellKnownTimestamp | undefined;
  concept: string | undefined;
  issues: common_TechCardIssue[] | undefined;
  sizeQuantities: common_TechCardSizeQuantity[] | undefined;
  signoffs: common_TechCardSignoff[] | undefined;
  patterns: common_TechCardSizePattern[] | undefined;
  // construction-description aspects with reference images (replaces the flat strings).
  details: common_TechCardDetail[] | undefined;
  // structural cut-pieces (детали кроя) + per-colourway fabric mapping (NF-05). Full-replace.
  pieces: common_TechCardPiece[] | undefined;
  // NF-07 auxiliary items. purpose is "sellable" (default/empty) or "auxiliary"; an auxiliary card
  // produces a packaging material rather than a product, so it may not link products and its run
  // output receipts into output_material_id (required before the first run; 0 = unset).
  purpose: common_TechCardPurpose | undefined;
  outputMaterialId: number | undefined;
  skuSeason: common_SkuSeason | undefined;
  // WS7: sub-classifies an auxiliary card (UNKNOWN=unset). Ignored / must be UNKNOWN for a sellable card.
  auxSubtype: common_TechCardAuxSubtype | undefined;
  // Planning date for the overdue view (production cockpit): the calendar day this style is planned
  // to drop, the anchor a run's promised_at is judged against ("до дропа N дней / просрочен"). Owner-
  // set intent, not a workflow stamp like approved_at/released_at — unset means no drop planned.
  // Only the DATE part is persisted (tech_card.target_drop_date is a DATE column); any time of day
  // sent on the wire is dropped. NOTE: a RELEASED card is frozen for edits (ErrTechCardReleased), so
  // this planning date is only settable while the card is draft/approved — see the store's freeze check.
  targetDropDate: wellKnownTimestamp | undefined;
  // DXF block-name → cut-piece aliases, scoped per fabric slot (§2.2). Presence-gated via the
  // wrapper (see TechCardPieceDxfAliasSet): absent = preserve stored, present = full replace.
  // Send the wrapper ONLY when the alias editor is wired, and always round-trip what was read —
  // the wrapper protects against a STALE client, not a half-implemented one: a client that
  // defaults to an empty PRESENT wrapper clears the whole table on every save.
  pieceDxfAliases: common_TechCardPieceDxfAliasSet | undefined;
  // ТРЕБУЕМЫЙ ПРИПУСК of this style, in CENTIMETRES (Ф3.2) — the right-hand side the readiness gate
  // compares a раскладка's recorded allowance against.
  // ABSENT = fall back to the workshop default (admin.WorkshopSettings.default_seam_allowance_cm),
  // which may itself be absent — and then there is NO STANDARD, and a consumer must answer «no
  // verdict» rather than substitute zero. Zero is legal here and states something specific: «the
  // выкройки of this model carry the cut line, no offset needed». Confusing «0» with «not
  // configured» would declare every раскладка with a 1 cm allowance in breach of a standard nobody
  // set.
  // NOT the free text construction.seam_allowances («5 мм»), which stays a human note. This is a
  // NUMBER a machine reads. It deliberately lives on the card header and not on the construction
  // section: any field added to a section's digest projection instantly marks EVERY signed-off
  // CONSTRUCTION approval as «edited since signing», on every card at once.
  requiredSeamAllowanceCm: googletype_Decimal | undefined;
};

// StyleNumberSource records how a tech card's style_number was set (PLM-rework Q1): GENERATED = the
// server proposed it from the season+sequence contract (SuggestStyleNumber); MANUAL = the owner
// overrode the proposal (the value then passes the strict format validator). UNKNOWN defaults to
// GENERATED on write.
export type common_StyleNumberSource =
  | "STYLE_NUMBER_SOURCE_UNKNOWN"
  | "STYLE_NUMBER_SOURCE_GENERATED"
  | "STYLE_NUMBER_SOURCE_MANUAL";
// TechCardStage is the development stage of a tech pack: prototype, fit sample,
// salesman sample, pre-production, production.
export type common_TechCardStage =
  | "TECH_CARD_STAGE_UNKNOWN"
  | "TECH_CARD_STAGE_PROTO"
  | "TECH_CARD_STAGE_FIT"
  | "TECH_CARD_STAGE_SMS"
  | "TECH_CARD_STAGE_PP"
  | "TECH_CARD_STAGE_PROD"
  | "TECH_CARD_STAGE_IDEA";
// TechCardApprovalState is the gating release state of a tech card, orthogonal to
// TechCardStage (which tracks development progress). A factory must only receive a
// card in the RELEASED state.
export type common_TechCardApprovalState =
  | "TECH_CARD_APPROVAL_STATE_UNKNOWN"
  | "TECH_CARD_APPROVAL_STATE_DRAFT"
  | "TECH_CARD_APPROVAL_STATE_IN_REVIEW"
  | "TECH_CARD_APPROVAL_STATE_APPROVED"
  | "TECH_CARD_APPROVAL_STATE_RELEASED"
  | "TECH_CARD_APPROVAL_STATE_OBSOLETE";
// TechCardMeasurementUnit is the unit for the card's geometry (callout dimensions).
// Metric only — the brand works in cm and mm, never inches.
export type common_TechCardMeasurementUnit =
  | "TECH_CARD_MEASUREMENT_UNIT_UNKNOWN"
  | "TECH_CARD_MEASUREMENT_UNIT_CM"
  | "TECH_CARD_MEASUREMENT_UNIT_MM";
// TechCardMediaItem is a writable sketch-media reference (id + kind).
export type common_TechCardMediaItem = {
  mediaId: number | undefined;
  kind: common_TechCardMediaKind | undefined;
  caption: string | undefined;
};

// TechCardMediaKind classifies a tech-card sketch image.
export type common_TechCardMediaKind =
  | "TECH_CARD_MEDIA_KIND_UNKNOWN"
  | "TECH_CARD_MEDIA_KIND_FRONT"
  | "TECH_CARD_MEDIA_KIND_BACK"
  | "TECH_CARD_MEDIA_KIND_DETAIL"
  | "TECH_CARD_MEDIA_KIND_LINING"
  | "TECH_CARD_MEDIA_KIND_PREVIEW"
  | "TECH_CARD_MEDIA_KIND_MOODBOARD"
  | "TECH_CARD_MEDIA_KIND_REFERENCE"
  | "TECH_CARD_MEDIA_KIND_SWATCH";
// TechCardCallout is a numbered detail note pointing at the technical sketch.
export type common_TechCardCallout = {
  number: number | undefined;
  part: string | undefined;
  description: string | undefined;
  dimensions: string | undefined;
  mediaId: number | undefined;
  posX: googletype_Decimal | undefined;
  posY: googletype_Decimal | undefined;
};

// TechCardBomItem is one bill-of-materials line — a catalog article (Sheet «Спецификация»).
// The per-colourway colour, placement and consumption live on TechCardColorwayUsage; the
// BOM line is now a pure material-article catalog entry.
export type common_TechCardBomItem = {
  section: common_TechCardBomSection | undefined;
  name: string | undefined;
  supplier: string | undefined;
  supplierRef: string | undefined;
  color: string | undefined;
  composition: string | undefined;
  spec: string | undefined;
  unit: string | undefined;
  unitPrice: googletype_Decimal | undefined;
  currency: string | undefined;
  comment: string | undefined;
  // fabric data for the cutter / marker (Phase 3.5c)
  // FULL roll width in cm, кромка INCLUDED — same correction as Material.fabric_width: this is what
  // effective_fabric_width_cm below resolves to, and that field's own text already derives the
  // usable cutting width as effective − 2 × selvedge.
  fabricWidth: googletype_Decimal | undefined;
  fabricWeightGsm: googletype_Decimal | undefined;
  // Nap / layout. OPTIONAL for presence, on the same reasoning as purpose/is_sample above: the
  // card is saved WHOLE, the admin is an SPA, and a tab holding an older bundle does not send this
  // field at all — a proto3 enum's zero value is UNKNOWN, so «absent» and «clear it» were the same
  // bytes and a stale tab would have wiped the направление off every line of the card. Silently:
  // the field is not in the signature digest, and NULL is indistinguishable from «ещё не задали».
  // Since Ф1 that erasure also un-saves every раскладка on the card, so absence now means «do not
  // touch» and only an explicitly-sent UNKNOWN clears the column.
  fabricDirection?: common_TechCardFabricDirection;
  wastagePercent: googletype_Decimal | undefined;
  // material_id optionally links this line to a catalog Material (task 10). The line keeps its
  // own snapshot fields regardless; 0 means unlinked (free-text / legacy).
  materialId: number | undefined;
  // id is the stable server-assigned PK (read-only). line_key is the client-generated ULID assigned
  // when the line is first created in the UI, round-tripped on every save so the server keyed-
  // reconciles by it (S2/S3) and keeps id stable — which is what lets operations/pieces/recipes hold
  // a real FK instead of a fragile positional index.
  id: number | undefined;
  lineKey: string | undefined;
  // Stored price provenance (production-costing Phase 3, plan 11). READ-ONLY — the server stamps
  // both on write and ignores anything a client sends here. price_source is 'manual' (the operator
  // typed/edited unit_price through a card save), 'catalog' (the reprice action pulled it from the
  // material catalog), or '' for a pre-provenance row whose origin is honestly unknown.
  priceSource: string | undefined;
  priceSnapshotAt: wellKnownTimestamp | undefined;
  // READ-ONLY width enrichment (0259, Ф9.1) — ignored on write, filled by the single-card read.
  // effective_fabric_width_cm = COALESCE(this line's fabric_width, linked article's width): the
  // width the раскладка should prefill instead of a hardcoded default. selvedge_cm is the linked
  // article's кромка per edge; usable cutting width = effective − 2×selvedge. Both unset when the
  // line is unlinked and carries no width of its own.
  effectiveFabricWidthCm: googletype_Decimal | undefined;
  selvedgeCm: googletype_Decimal | undefined;
  // НАЗНАЧЕНИЕ (0265) — see TechCardBomPurpose. Accepted only on a ROLL-GOODS line (fabric, lining,
  // interlining, insulation): those are the four families cloth is measured and laid out by, and a
  // purpose on a thread or a button would be data no screen ever shows and the later pattern-binding
  // work would have to un-pick. UNSET is legal everywhere and is what an unsorted line carries.
  // OPTIONAL, и это несущее. Админка — SPA на Vercel, вкладки живут через деплои, а карточка
  // сохраняется целиком. Без явного присутствия старый бандл, который про эти поля не знает,
  // прислал бы proto3-дефолты — UNSET и false, — и сохранение стёрло бы назначение у ВСЕХ строк
  // карточки. Стирание было бы вдобавок бесследным: этих полей нет в дайджесте подписи, а NULL
  // неотличим от «ещё не разложили». Отсутствие поля означает «не трогай», а не «очисти».
  purpose?: common_TechCardBomPurpose;
  // Free-text explanation, accepted ONLY when purpose is OTHER (rejected otherwise, and the DB
  // agrees via chk_bom_item_purpose_note). Optional even then: "другое" without an explanation is a
  // real answer, and demanding one just farms junk text.
  // Optional по той же причине, что и purpose — отсутствие означает «не трогай».
  purposeNote?: string;
  // Семпловая: this line is the yardage the SAMPLE is sewn from. A flag, not a ninth purpose — a
  // sample is assembled from a sample MAIN plus a sample LINING, and as a purpose value both would
  // collapse into one bucket and lose the role that makes them useful.
  // Optional по той же причине: голый bool от старого бандла приходит как false и снял бы признак
  // со всех строк карточки разом.
  isSample?: boolean;
  // READ-ONLY (Ф5а.3): the vocabulary normalisation of this line's `unit`. Ignored on write — the
  // stored value stays the free-text `unit`, deliberately: that column is inside the SIGNED MATERIALS
  // digest, so respelling «м» → "m" in storage would stale the MATERIALS sign-off of every card that
  // spells a unit non-canonically, for a change that alters nothing the card BUYS. Comparison against
  // the article's unit is normalised in the server instead, which costs no sign-off.
  // UNKNOWN = the free text does not map to a known unit; it is NOT "no unit".
  unitCode: common_MaterialUnit | undefined;
  // ЧТО ЭТО ЗА ПОЗИЦИЯ (0276) — see TechCardBomKind. The mirror of `purpose` above: accepted only on
  // a line that is NEITHER roll goods NOR a label (hardware, thread, packaging, trim, decoration,
  // other), and only in the kind's own home section — `zipper` on a thread line is refused with a
  // field-tagged error, not stored. UNSET is legal everywhere and is what an unclassified line
  // carries.
  // OPTIONAL for the same load-bearing reason as `purpose`: the admin is an SPA, tabs survive
  // deploys, and the card is saved WHOLE. A bare proto3 enum from a bundle that predates this field
  // arrives as UNSET and would wipe the classification off EVERY line of the card — silently, since
  // `kind` is deliberately outside the signed MATERIALS digest and NULL is indistinguishable from
  // "not classified yet". Absence means «не трогай»; an explicitly sent UNSET still clears.
  kind?: common_TechCardBomKind;
  // Free-text explanation, accepted ONLY when kind is OTHER (rejected otherwise, and the DB agrees
  // via chk_bom_item_kind_note). Optional even then — «другое» with no note is a real answer.
  // It travels as ONE UNIT with `kind`: the DB couples the two columns, so a save that rewrote one
  // and left the other alone could hand MySQL a row it must refuse. Sending either field means both
  // are being written; sending neither means «не трогай» both.
  kindNote?: string;
};

// TechCardBomSection groups a BOM line by material family (Sheet «Спецификация»).
export type common_TechCardBomSection =
  | "TECH_CARD_BOM_SECTION_UNKNOWN"
  | "TECH_CARD_BOM_SECTION_FABRIC"
  | "TECH_CARD_BOM_SECTION_LINING"
  | "TECH_CARD_BOM_SECTION_INTERLINING"
  | "TECH_CARD_BOM_SECTION_INSULATION"
  | "TECH_CARD_BOM_SECTION_HARDWARE"
  | "TECH_CARD_BOM_SECTION_THREAD"
  | "TECH_CARD_BOM_SECTION_LABEL"
  | "TECH_CARD_BOM_SECTION_PACKAGING"
  | "TECH_CARD_BOM_SECTION_TRIM"
  | "TECH_CARD_BOM_SECTION_DECORATION"
  | "TECH_CARD_BOM_SECTION_OTHER";
// TechCardFabricDirection is the cutting layout a fabric requires.
export type common_TechCardFabricDirection =
  | "TECH_CARD_FABRIC_DIRECTION_UNKNOWN"
  | "TECH_CARD_FABRIC_DIRECTION_ANY"
  | "TECH_CARD_FABRIC_DIRECTION_ONE_WAY"
  | "TECH_CARD_FABRIC_DIRECTION_TWO_WAY";
// TechCardBomPurpose is НАЗНАЧЕНИЕ — what the garment uses a roll-goods line FOR, on its own axis
// beside `section` (0265). Several lines legitimately share one purpose; that IS the point, the
// field exists to name a SUBSET of fabrics ("the lining ones", "the contrast ones").
// It is not a section value. `section` drives the wastage gross-up, the composition derive and what
// a раскладка may bind to, and a pocket-bag / contrast / mesh fabric is genuinely fabric on all
// three counts — it differs only in role. It is not free text either: the field exists to GROUP, and
// a free-text role stops grouping the moment two operators spell it differently. Hence a closed
// eight-value list, with `other` carrying its meaning in the SEPARATE purpose_note field so a note
// can never become a shadow purpose on one of the seven real values.
// UNSET (0) is a first-class state meaning "not sorted yet", not a default. Every line that existed
// before 0265 is UNSET on purpose: section='fabric' is exactly where pocket-bag, contrast and mesh
// hide today, so a backfill would have labelled them MAIN confidently and wrongly.
export type common_TechCardBomPurpose =
  | "TECH_CARD_BOM_PURPOSE_UNSET"
  | "TECH_CARD_BOM_PURPOSE_MAIN"
  | "TECH_CARD_BOM_PURPOSE_LINING"
  | "TECH_CARD_BOM_PURPOSE_POCKETING"
  | "TECH_CARD_BOM_PURPOSE_INTERFACING"
  | "TECH_CARD_BOM_PURPOSE_INSULATION"
  | "TECH_CARD_BOM_PURPOSE_CONTRAST"
  | "TECH_CARD_BOM_PURPOSE_MESH"
  | "TECH_CARD_BOM_PURPOSE_OTHER";
// MaterialUnit is the closed vocabulary a material quantity is measured in (Ф5а.3), mirroring
// entity.MaterialUnit. Before it, every unit was free text and every consumer compared raw strings:
// the production material plan carried a private metre synonym set (m/м/meter/meters/metre/metres)
// and degraded into a caveat on any other mismatch, so a slot spelled «м» against an article spelled
// "m" counted as two different units — the quantity kept the slot's meaning while being compared
// against the article's stock, and the pinned-article costing path refused to price the line.
// READ-ONLY on the wire. The stored value stays the free-text `unit` string (which is what a write
// sets); unit_code is the server's normalisation of it, so a value the vocabulary does not know is
// never guessed — it arrives as MATERIAL_UNIT_UNKNOWN with the raw string intact beside it, and the
// set of rows reporting UNKNOWN is precisely the list of units that still need a human. A client
// must therefore never treat UNKNOWN as "no unit" or as "clear the unit".
export type common_MaterialUnit =
  | "MATERIAL_UNIT_UNKNOWN"
  | "MATERIAL_UNIT_M"
  | "MATERIAL_UNIT_CM"
  | "MATERIAL_UNIT_MM"
  | "MATERIAL_UNIT_M2"
  | "MATERIAL_UNIT_G"
  | "MATERIAL_UNIT_KG"
  | "MATERIAL_UNIT_PCS"
  | "MATERIAL_UNIT_PAIR"
  | "MATERIAL_UNIT_SET"
  | "MATERIAL_UNIT_CONE"
  | "MATERIAL_UNIT_ROLL";
// TechCardBomKind is ЧТО ЭТО ЗА ПОЗИЦИЯ — the mirror image of TechCardBomPurpose (0265). Purpose
// says what the garment uses a ROLL-GOODS line FOR; kind says what a NON-roll-goods line IS. The
// two never meet on the same row: purpose is legal only on fabric/lining/interlining/insulation,
// kind only on the sections that are neither roll goods nor label.
// NOT CALLED "role". TechCardRole (designer/constructor/technologist/…) already exists in this file
// and names WHO is responsible for a card. A second "role" meaning "what this button is" would be
// misread permanently, by people and by grep alike.
// ONE FLAT ENUM, NOT ONE PER FAMILY. The value already implies its family — a `zipper` is hardware
// and nothing else — so a per-family enum would encode the section twice and let the two copies
// disagree, which is the drift class 0265's own header argues against. The pairing (each kind is
// legal only in its HOME section) is therefore data, not type: entity.bomKindHomeSection is the
// single table, and the store checks the pair on write. The DB CHECK closes the VOCABULARY only —
// it never sees the section, deliberately, because a two-column CHECK would fire as a raw MySQL
// 3819 on an UPDATE that touched only `section` and name a column the operator never edited.
// WHY `label` IS NOT ELIGIBLE. tech_card_label.label_type already owns that vocabulary
// (main/size/care/origin/flag/hangtag/barcode/special), several label SPEC rows may point at ONE
// bom_item_id (the material they print on), and labelsProjection already hashes label_type into the
// signed LABELS digest. A `kind` on section=label would be a second, unsigned answer to a question
// that is already answered and already signed.
// UNSET (0) is a first-class state meaning "not classified yet", not a default. Nothing is
// backfilled: every line that predates 0276 is genuinely unclassified, and a guess ("this thread is
// sewing_thread") would read as a fact and be believed.
// СПОРНЫЕ СЛУЧАИ, решённые здесь и больше нигде — граница проходит по ФУНКЦИИ, не по материалу:
// * велкро/липучка → HOOK_LOOP, это TRIM (мягкая лента, метраж), а не фурнитура;
// * заклёпка, которая ДЕРЖИТ (карман, шлёвку) → RIVET, hardware;
// * такая же по виду декоративная клёпка, которая ничего не держит → STUD, decoration;
// * шнур → DRAWCORD, trim (продаётся метражом); его фиксатор → CORD_STOPPER, hardware (штучный).
export type common_TechCardBomKind =
  | "TECH_CARD_BOM_KIND_UNSET"
  // ФУРНИТУРА — section=hardware. Countable fittings; the garment stops working without them.
  | "TECH_CARD_BOM_KIND_ZIPPER"
  | "TECH_CARD_BOM_KIND_ZIPPER_SLIDER"
  | "TECH_CARD_BOM_KIND_BUTTON"
  | "TECH_CARD_BOM_KIND_SNAP"
  | "TECH_CARD_BOM_KIND_RIVET"
  | "TECH_CARD_BOM_KIND_EYELET"
  | "TECH_CARD_BOM_KIND_HOOK_AND_BAR"
  | "TECH_CARD_BOM_KIND_SNAP_HOOK"
  | "TECH_CARD_BOM_KIND_BUCKLE"
  | "TECH_CARD_BOM_KIND_STRAP_ADJUSTER"
  | "TECH_CARD_BOM_KIND_RING"
  | "TECH_CARD_BOM_KIND_TOGGLE"
  | "TECH_CARD_BOM_KIND_CORD_STOPPER"
  | "TECH_CARD_BOM_KIND_CORD_END"
  | "TECH_CARD_BOM_KIND_MAGNET"
  | "TECH_CARD_BOM_KIND_CHAIN"
  // ОТДЕЛОЧНЫЕ МАТЕРИАЛЫ — section=trim. Soft goods sold by length; they keep their wastage gross-up.
  | "TECH_CARD_BOM_KIND_ELASTIC"
  | "TECH_CARD_BOM_KIND_DRAWCORD"
  | "TECH_CARD_BOM_KIND_BINDING"
  | "TECH_CARD_BOM_KIND_TAPE"
  | "TECH_CARD_BOM_KIND_PIPING"
  | "TECH_CARD_BOM_KIND_WEBBING"
  | "TECH_CARD_BOM_KIND_HOOK_LOOP"
  | "TECH_CARD_BOM_KIND_BONING"
  | "TECH_CARD_BOM_KIND_LACE"
  | "TECH_CARD_BOM_KIND_RIBBING"
  // ДЕКОР — section=decoration. Applied ONTO the garment; nothing here holds anything together.
  | "TECH_CARD_BOM_KIND_PRINT"
  | "TECH_CARD_BOM_KIND_EMBROIDERY"
  | "TECH_CARD_BOM_KIND_APPLIQUE"
  | "TECH_CARD_BOM_KIND_PATCH"
  | "TECH_CARD_BOM_KIND_HEAT_TRANSFER"
  | "TECH_CARD_BOM_KIND_RHINESTONE"
  | "TECH_CARD_BOM_KIND_SEQUIN"
  | "TECH_CARD_BOM_KIND_STUD"
  | "TECH_CARD_BOM_KIND_FOIL"
  | "TECH_CARD_BOM_KIND_LASER"
  // НИТКИ — section=thread. Split by the JOB the thread does, which is what picks the machine.
  | "TECH_CARD_BOM_KIND_SEWING_THREAD"
  | "TECH_CARD_BOM_KIND_TOPSTITCH_THREAD"
  | "TECH_CARD_BOM_KIND_OVERLOCK_THREAD"
  | "TECH_CARD_BOM_KIND_BUTTONHOLE_THREAD"
  | "TECH_CARD_BOM_KIND_EMBROIDERY_THREAD"
  | "TECH_CARD_BOM_KIND_ELASTIC_THREAD"
  // УПАКОВКА — section=packaging. Spellings deliberately match TechCardAuxSubtype wherever the two
  // name the SAME object (sticker / dust_bag / garment_case / hanger), so an auxiliary card that
  // MAKES the item and the BOM line that CONSUMES it read as one word. The three that differ do so
  // because the object differs: HANGTAG_STRING is the string, not the aux HANGTAG it hangs;
  // INSERT_CARD is a printed card, narrower than the aux INSERT; CARTON is the outer shipping box
  // (TechCardPackaging.units_per_box / box_marking), not the aux BOX the customer receives.
  | "TECH_CARD_BOM_KIND_POLYBAG"
  | "TECH_CARD_BOM_KIND_CARTON"
  | "TECH_CARD_BOM_KIND_HANGER"
  | "TECH_CARD_BOM_KIND_HANGTAG_STRING"
  | "TECH_CARD_BOM_KIND_STICKER"
  | "TECH_CARD_BOM_KIND_TISSUE"
  | "TECH_CARD_BOM_KIND_DUST_BAG"
  | "TECH_CARD_BOM_KIND_GARMENT_CASE"
  | "TECH_CARD_BOM_KIND_INSERT_CARD"
  // ДРУГОЕ — the ONLY value legal in EVERY eligible section (including section=other, which has no
  // kinds of its own). Its meaning lives in the separate kind_note, never in a shadow value on one
  // of the 51 real kinds — the same containment chk_bom_item_purpose_note gives назначению.
  | "TECH_CARD_BOM_KIND_OTHER";
// TechCardConstruction holds general workmanship parameters (Sheet «Обработка»).
export type common_TechCardConstruction = {
  mainStitchType: string | undefined;
  stitchDensity: string | undefined;
  overlockThreads: string | undefined;
  seamAllowances: string | undefined;
  hemFinish: string | undefined;
  pressing: string | undefined;
  machineClass: string | undefined;
  notes: string | undefined;
};

// TechCardOperation is one per-node sewing operation (Sheet «Обработка»).
export type common_TechCardOperation = {
  node: string | undefined;
  description: string | undefined;
  seamType: string | undefined;
  stitchesPerCm: googletype_Decimal | undefined;
  topstitchWidth: string | undefined;
  thread: string | undefined;
  note: string | undefined;
  operationNumber: number | undefined;
  machine: string | undefined;
  seamAllowance: string | undefined;
  needle: string | undefined;
  timeNorm: googletype_Decimal | undefined;
  attachment: string | undefined;
  operationType: common_TechCardOperationType | undefined;
  // 0-based index into TechCardInsert.bom_items of the material this operation
  // applies (thread / binding (бейка) / interlining / zipper) when it is NOT resolved
  // through a part. Uses proto3 explicit presence so index 0 (the first BOM line) is
  // distinguishable from "no material": unset = no reference. When set, it wins; the
  // colour resolves via the selected colourway's usage with the same bom_item_index.
  bomItemIndex?: number;
  calloutNumber: number | undefined;
  zone: common_TechCardConstructionZone | undefined;
  placement: string | undefined;
  // via the selected colourway's usages (match trim+lower; bom_item_index wins if set)
  // bom_line_key references the BOM line by its stable line_key (WS3 follow-up: take positionality off
  // the wire). Preferred over the positional bom_item_index (kept for the transition). The store
  // resolves it to bom_item_id, the real FK on read.
  bomLineKey: string | undefined;
  bomItemId: number | undefined;
  // piece_line_keys references the cut-pieces this operation works on, by their stable
  // TechCardPiece.line_key (WS4) — the same durable reference TechCardColorwayUsage.piece_line_key
  // uses. REPEATED, unlike the usage's single key, because an assembly operation genuinely spans
  // pieces and there is no useful bound on how many. A consumption norm, by contrast, is about
  // exactly one piece, which is why that side stays 1:1. Empty = not tied to specific pieces.
  // `placement` above stays the human label (PDF/legacy) and is not a join key.
  pieceLineKeys: string[] | undefined;
  pieceIds: number[] | undefined;
  // bom_line_keys references the BOM lines this operation itself consumes -- the off-part materials
  // (thread, fusing) it joins with -- by their stable line_key. REPEATED for the same reason
  // piece_line_keys is: one operation can join several materials. Supersedes the single
  // bom_line_key = 19, which stays for the transition and is read as the first entry when this is
  // empty. Distinct from piece_line_keys: those are the parts joined, these are what joins them.
  bomLineKeys: string[] | undefined;
  bomItemIds: number[] | undefined;
  // smv is the standard minute value and supersedes time_norm above: minute rollups
  // (TechCardCosting.total_sam) take smv when it is set and fall back to time_norm when it is not,
  // so re-timing an operation means writing smv, not rewriting the legacy column. Absent = unset.
  smv: googletype_Decimal | undefined;
};

// TechCardOperationType classifies an operation by its machine / stitch class
// (replaces the coarse seaming/overlock/decorative split with the real sewing
// taxonomy the factory works in).
export type common_TechCardOperationType =
  | "TECH_CARD_OPERATION_TYPE_UNKNOWN"
  | "TECH_CARD_OPERATION_TYPE_LOCKSTITCH"
  | "TECH_CARD_OPERATION_TYPE_DOUBLE_NEEDLE"
  | "TECH_CARD_OPERATION_TYPE_OVERLOCK"
  | "TECH_CARD_OPERATION_TYPE_COVERSTITCH"
  | "TECH_CARD_OPERATION_TYPE_CHAINSTITCH"
  | "TECH_CARD_OPERATION_TYPE_BLINDHEM"
  | "TECH_CARD_OPERATION_TYPE_BARTACK"
  | "TECH_CARD_OPERATION_TYPE_BUTTONHOLE"
  | "TECH_CARD_OPERATION_TYPE_BUTTON_ATTACH"
  | "TECH_CARD_OPERATION_TYPE_FUSING"
  | "TECH_CARD_OPERATION_TYPE_HANDWORK"
  | "TECH_CARD_OPERATION_TYPE_OTHER";
// TechCardConstructionZone groups an operation for display only. Construction stays
// a single ordered list; the zone is just a visual band (outer shell, lining, …).
export type common_TechCardConstructionZone =
  | "TECH_CARD_CONSTRUCTION_ZONE_UNKNOWN"
  | "TECH_CARD_CONSTRUCTION_ZONE_OUTER"
  | "TECH_CARD_CONSTRUCTION_ZONE_LINING"
  | "TECH_CARD_CONSTRUCTION_ZONE_INTERLINING"
  | "TECH_CARD_CONSTRUCTION_ZONE_OTHER";
// TechCardLabel is one label / tag spec (Sheet «Этикетки и упаковка»).
// TechCardLabel is the garment's label/tag SPEC — one of the three historically-unconnected "label"
// concepts (S21): (a) THIS spec, (b) the shipment label (common/shipment.proto — a shipping document,
// deliberately NOT merged, a different domain), (c) the label MATERIAL as a BOM line
// (tech_card_bom_item, section=label). WS7 unifies (a)↔(c) via bom_item_id below, and classifies the
// auxiliary item via TechCard.aux_subtype. DEPRECATION (destructive → M3, not done here): once
// bom_item_id + aux_subtype are adopted, label_type collapses into aux_subtype and the free-text
// content/placement/attachment/size overlap (also carried structurally by the linked material + the
// assembly bill's print_note/position_note) is dropped in a guarded migration.
export type common_TechCardLabel = {
  labelType: common_TechCardLabelType | undefined;
  content: string | undefined;
  placement: string | undefined;
  attachment: string | undefined;
  size: string | undefined;
  note: string | undefined;
  // WS7/§2.8 (S21 unification bridge): FK to the physical label material's BOM line
  // (tech_card_bom_item). 0 = unlinked. Links this free-text label SPEC to the material it prints on.
  bomItemId: number | undefined;
};

// TechCardLabelType classifies a label / tag (Sheet «Этикетки и упаковка»).
export type common_TechCardLabelType =
  | "TECH_CARD_LABEL_TYPE_UNKNOWN"
  | "TECH_CARD_LABEL_TYPE_MAIN"
  | "TECH_CARD_LABEL_TYPE_SIZE"
  | "TECH_CARD_LABEL_TYPE_CARE"
  | "TECH_CARD_LABEL_TYPE_ORIGIN"
  | "TECH_CARD_LABEL_TYPE_FLAG"
  | "TECH_CARD_LABEL_TYPE_HANGTAG"
  | "TECH_CARD_LABEL_TYPE_BARCODE"
  | "TECH_CARD_LABEL_TYPE_SPECIAL";
// TechCardPackaging holds the packaging spec (Sheet «Этикетки и упаковка»).
export type common_TechCardPackaging = {
  foldingMethod: string | undefined;
  polybag: string | undefined;
  bagSticker: string | undefined;
  inserts: string | undefined;
  unitsPerBox: number | undefined;
  boxMarking: string | undefined;
  boxDimensions: string | undefined;
  weightNetGrams: number | undefined;
  weightGrossGrams: number | undefined;
  notes: string | undefined;
};

// TechCardCosting holds the manually-entered per-unit cost articles (Sheet «Калькуляция»).
// Everything is in a SINGLE currency. The materials line and the unit/order totals are
// COMPUTED on read (output-only, ignored on write). Model: cost is built per GARMENT, then
// scaled to the whole order by order_qty. There is NO pricing here — markup/wholesale/retail
// were removed; pricing lives on the published product.
export type common_TechCardCosting = {
  // manual per-unit cost articles (per ONE garment), all in `currency`.
  cmtCost: googletype_Decimal | undefined;
  logisticsCost: googletype_Decimal | undefined;
  overheadCost: googletype_Decimal | undefined;
  defectPercent: googletype_Decimal | undefined;
  currency: string | undefined;
  notes: string | undefined;
  // target_margin_pct is the gross margin this STYLE is expected to make, 0..100. It is the number
  // the costing waterfall measures the achieved margin against; without it the admin had to carry a
  // hard-coded house constant. 0 / unset = fall back to the house default (alert_setting
  // `target_margin_pct`), which is what effective_target_margin_pct below resolves to.
  targetMarginPct: googletype_Decimal | undefined;
  // OUTPUT-ONLY computed rollup (ignored on write). Root figures are the PRIMARY colourway
  // (colorways index 0); per-colourway figures are in colorway_costs. Materials come from the
  // BOM via each colourway's usages, normalised to a PER-GARMENT figure (a usage graded only
  // per size is divided by order_qty), then taken in the single `currency` — a BOM line in
  // another currency is flagged in has_unconverted_currencies and left out of materials_per_unit
  // (it still appears in materials_total under its own currency, never silently dropped).
  materialsTotal: common_TechCardCostLine[] | undefined;
  materialsPerUnit: googletype_Decimal | undefined;
  unitCost: googletype_Decimal | undefined;
  orderQty: number | undefined;
  orderCost: googletype_Decimal | undefined;
  hasUnconvertedCurrencies: boolean | undefined;
  // OUTPUT-ONLY: set when at least one authored usage of the PRIMARY colourway could not be costed
  // at all (no price / unresolvable pin / no norm / per-size norms without order qty); such a line
  // contributes to NO currency bucket, so unit_cost/unit_cost_base are withheld from cost seeding
  // and should not be trusted as complete.
  hasUnpriced: boolean | undefined;
  totalSam: googletype_Decimal | undefined;
  colorwayCosts: common_TechCardColorwayCost[] | undefined;
  // OUTPUT-ONLY base-currency rollup. The unit/order cost of the primary colourway folded into
  // the base currency via the manual costing FX rates. Set ONLY when every currency involved
  // has a rate — this is the figure the product-cost seed uses, so a non-base costing can seed
  // cost_price too. Absent when a needed rate is missing (then has_unconverted_currencies).
  unitCostBase: googletype_Decimal | undefined;
  orderCostBase: googletype_Decimal | undefined;
  baseCurrency: string | undefined;
  // OUTPUT-ONLY: the target margin actually in force for this style — target_margin_pct above when
  // set, otherwise the house default from alert_setting. Resolved here so the costing tab needs one
  // read (already gated by costing:read) instead of a second, analytics-gated settings call.
  effectiveTargetMarginPct: googletype_Decimal | undefined;
  // OUTPUT-ONLY VAT context for the margin on this read: which country's rate the colourway
  // net_prices were computed at, and what that rate is. Surfaced so the tab can SAY which market it
  // is showing a margin for instead of presenting one number as if it were universal.
  // The rate comes from the same `vat_rate` table the order snapshot, the accounting VAT engine and
  // the margin-by-style report read — deliberately not a second, costing-owned copy that could drift
  // from them. vat_rate_pct is unset when the country has no rate on file (export: nothing to net).
  vatCountryCode: string | undefined;
  vatRatePct: googletype_Decimal | undefined;
};

// TechCardCostLine is one currency bucket of the materials rollup.
export type common_TechCardCostLine = {
  currency: string | undefined;
  amount: googletype_Decimal | undefined;
};

// TechCardColorwayCost is the computed cost of ONE colourway (Sheet «Калькуляция»),
// OUTPUT-ONLY (ignored on write). Materials come from that colourway's usages; the manual
// articles (CMT/hardware/…) are shared across colourways, so unit_cost folds them in. All
// figures are per GARMENT except order_cost (whole run). No FX conversion.
export type common_TechCardColorwayCost = {
  colorwayId: number | undefined;
  materialsTotal: common_TechCardCostLine[] | undefined;
  materialsPerUnit: googletype_Decimal | undefined;
  unitCost: googletype_Decimal | undefined;
  orderQty: number | undefined;
  orderCost: googletype_Decimal | undefined;
  hasUnconvertedCurrencies: boolean | undefined;
  // OUTPUT-ONLY: set when at least one authored usage of THIS colourway could not be costed at all
  // (no price / unresolvable pin / no norm / per-size norms without order qty); such a line
  // contributes to NO currency bucket, so unit_cost is withheld from cost seeding for this
  // colourway and should not be trusted as complete.
  hasUnpriced: boolean | undefined;
};

// TechCardIssue is a maker-flagged problem ("this seam is impossible") against an
