export type ListTechCardsResponse = {
  techCards: common_TechCardListItem[] | undefined;
  total: number | undefined;
};

// TechCardListItem is a lightweight tech-card header for list views.
export type common_TechCardListItem = {
  id: number | undefined;
  styleNumber: string | undefined;
  name: string | undefined;
  brand: string | undefined;
  stage: common_TechCardStage | undefined;
  status: string | undefined;
  targetGender: common_GenderEnum | undefined;
  createdAt: wellKnownTimestamp | undefined;
  updatedAt: wellKnownTimestamp | undefined;
  approvalState: common_TechCardApprovalState | undefined;
  lockVersion: number | undefined;
  // Thumbnail URL for a grid/gallery view (idea gallery). For an IDEA card it is the first
  // moodboard image; otherwise the PREVIEW-kind sketch (falling back to the first technical, then any
  // media). Empty when the card has no media. Resolved server-side to avoid an N+1 GetTechCard.
  previewUrl: string | undefined;
  // Card purpose: "sellable" (default) or "auxiliary" (NF-07). Lets a board/list badge auxiliary
  // cards (dust bags, shoppers…) without an N+1 GetTechCard, mirroring TechCard.purpose.
  purpose: common_TechCardPurpose | undefined;
  skuSeason: common_SkuSeason | undefined;
  // WS7: auxiliary sub-type badge for list views (UNKNOWN=unset), mirroring purpose above.
  auxSubtype: common_TechCardAuxSubtype | undefined;
  // Category of the style, so a list/board can group and label by category without an N+1
  // GetTechCard. category_id is the leaf tag; the top/sub/type triple is the derived taxonomy path
  // (0 = unset) — the same columns ListTechCardsRequest.category_ids filters on.
  categoryId: number | undefined;
  topCategoryId: number | undefined;
  subCategoryId: number | undefined;
  typeId: number | undefined;
  // colorway_count is how many LIVE (non-archived) colourways the style has — the number a list row
  // shows next to a style. Resolved server-side in one batched query for the page, never N+1.
  // NOTE: unrelated to MarginByStyleRow.colorway_count, which counts SKUs that SOLD.
  colorwayCount: number | undefined;
  // Auxiliary output material (NF-07): the warehouse material an auxiliary card's run receipts into,
  // plus its name and on-hand balance. Zero/empty for a sellable card. Present so an aux picker can
  // show "820 on hand" beside a dust bag from the list alone — it previously needed one GetTechCard
  // per card plus a warehouse read.
  outputMaterialId: number | undefined;
  outputMaterialName: string | undefined;
  outputMaterialOnHand: googletype_Decimal | undefined;
  // Colour variants of that output (0252), summarised for the row: how many colours the card
  // produces and what the warehouse holds across them ("3 colours · 820 on hand"). ACTIVE variants
  // only — the badge answers "what can I plan", not "what has ever existed". 0/unset means the card
  // is in legacy single-output mode, where output_material_* above is the whole answer.
  outputVariantCount: number | undefined;
  outputVariantsOnHand: googletype_Decimal | undefined;
  // How many saved раскладки (markers, 0257) the card carries, batched for the page like
  // colorway_count. The COUNT only — a "latest consumption" here would be a lie without naming
  // the size and the BOM slot it was measured for.
  markerCount: number | undefined;
};

// TechCardReadinessRequirement is ONE condition on a style's progress, evaluated server-side against
// the real data. `key` is the stable machine name (switch on it); `label` is the sentence to show.
export type TechCardReadinessRequirement = {
  key: string | undefined;
  label: string | undefined;
  met: boolean | undefined;
  detail: string | undefined;
  // UNKNOWN — the server COULD NOT ANSWER this row. Not «unmet», and above all not «met».
  // It exists for one row today, `patterns`, and the reason is that the row was LYING. It counted
  // DISTINCT tech_card_size_pattern.size_id against the size range, but the client files every
  // sheet of a card under the SMALLEST size of the range as a pure storage artefact — so a card with
  // five sizes and one graded DXF read as «1 of 5» and could never satisfy the prod checklist,
  // while a card with one flat sheet per size read as fully covered whether or not those files
  // contain those sizes.
  // A false PASS is the worse of the two states, so the row stops asserting «verified» immediately
  // rather than waiting for the index to fill. UNKNOWN does not count as unmet, so NO card becomes
  // newly blocked at deploy time — the only thing that changes is that the server stops lying. The
  // real check switches itself on card by card as the Ф6.3 size index (PutTechCardPatternSizeIndex)
  // is populated.
  // A row with unknown = true always carries a `detail` saying WHY there is no verdict, and `met` is
  // false. `*_ready` booleans on this response are computed as «no row is unmet», with unknown rows
  // skipped — a client recomputing readiness from the rows must do the same.
  unknown: boolean | undefined;
};

// GetTechCardReadiness answers "what is missing before this style can move on" — the checklist the
// admin used to keep as a client-side table with no way to know if it matched the backend.
// ADVISORY, NOT A GATE. Stage and approval_state remain free-standing fields on UpdateTechCard: this
// RPC reports, it does not authorise, and nothing here blocks a save. The only stage rule the server
// ENFORCES is still the backward one (a style with samples/releases/colourways cannot regress).
export type GetTechCardReadinessRequest = {
  techCardId: number | undefined;
};

export type GetTechCardReadinessResponse = {
  currentStage: common_TechCardStage | undefined;
  nextStage: common_TechCardStage | undefined;
  // Conditions for entering next_stage, in the order they should be shown. Empty when there is no
  // next stage.
  nextStageRequirements: TechCardReadinessRequirement[] | undefined;
  nextStageReady: boolean | undefined;
  // Conditions for releasing the card to the factory (approval_state = RELEASED). Independent of the
  // stage checklist: a card can be sampling-complete and still un-releasable.
  releaseRequirements: TechCardReadinessRequirement[] | undefined;
  releaseReady: boolean | undefined;
};

// GetStylePipeline is the development board: one column per lifecycle stage
