// Material catalog (task 10). Create/Update send a common.Material; server-managed fields
// (id on create, archived, latest_price) are ignored on write.
export type CreateMaterialRequest = {
  material: common_Material | undefined;
};

export type common_Material = {
  id: number | undefined;
  name: string | undefined;
  section: common_TechCardBomSection | undefined;
  supplier: string | undefined;
  supplierRef: string | undefined;
  composition: string | undefined;
  spec: string | undefined;
  // Free text, stored EXACTLY as sent — the server never respells it, so a client that writes "pc"
  // reads back "pc". unit_code below is the server's read-only normalisation of this string, and it
  // is what comparisons run on; migration 0271 collapsed the legacy catalogue spellings once, but
  // that was a cleanup, not a standing write rule.
  unit: string | undefined;
  // FULL roll width in cm, кромка INCLUDED — despite what this comment said until Ф5а.4. Nothing has
  // ever subtracted the selvedge from it (0259 says so explicitly: the flat copy was labelled
  // "usable" in 0095 but no consumer ever treated it as such), and both EffectiveFabricWidthCm and
  // the metres→kg conversion depend on it being the full width: the selvedge is bought, it weighs,
  // and billing by the cutting width understates the invoiced weight by 2–4% every time. The USABLE
  // cutting width is this minus 2 × MaterialFabricAttrs.selvedge_cm.
  fabricWidth: googletype_Decimal | undefined;
  fabricWeightGsm: googletype_Decimal | undefined;
  archived: boolean | undefined;
  // latest_price is the current (latest-effective) price, if any (read-only; set via
  // AddMaterialPrice). Absent when the material has no price history yet.
  latestPrice: common_MaterialPrice | undefined;
  // Warehouse catalog fields (new-flow NF-02).
  code: string | undefined;
  color: string | undefined;
  pantone: string | undefined;
  minStock: googletype_Decimal | undefined;
  notes: string | undefined;
  // lock_version is the optimistic-lock counter (S25, read-only). Echo it back in
  // UpdateMaterialRequest.expected_lock_version; a stale value is rejected (Aborted).
  lockVersion: number | undefined;
  // CTI typing (S15): material_class selects which typed attribute set applies. Exactly one of the
  // `attributes` oneof is populated for the four typed classes; other_attrs (a JSON object) is the
  // escape-hatch used only when material_class = MATERIAL_CLASS_OTHER.
  materialClass: common_MaterialClass | undefined;
  fabricAttrs?: common_MaterialFabricAttrs;
  hardwareAttrs?: common_MaterialHardwareAttrs;
  threadAttrs?: common_MaterialThreadAttrs;
  packagingAttrs?: common_MaterialPackagingAttrs;
  otherAttrs: string | undefined;
  // Structural fibre composition (S17): fiber_code + percent, summing to 100 when present. Replaces
  // the free-text `composition` string (which stays legacy plain text). On write, only fiber_code +
  // percent are read (name is resolved server-side from the fibre dictionary). Empty = unset. A
  // shell-fabric material's composition is what a style's derived composition_entries is built from.
  compositionEntries: common_CompositionEntry[] | undefined;
  // Catalog image (#39): image_id is the write-side media reference (FK media(id); 0 = unset); image
  // is the resolved MediaFull on read (null when unset). Mirrors Model.thumbnail_id / Model.thumbnail.
  imageId: number | undefined;
  image: common_MediaFull | undefined;
  // purpose (#40) marks whether the material is used for samples, production, or both. Defaults to
  // BOTH on write when UNKNOWN, so the admin can mark and filter materials.
  purpose: common_MaterialPurpose | undefined;
  // Procurement quick wins (Phase 9, plan 13 §1 — the PO entity was cut): supplier_id links to the
  // supplier CATALOG (the free-text `supplier` field stays legacy), lead_time_days is the typical
  // order-to-door time. 0 = unset for both.
  supplierId: number | undefined;
  leadTimeDays: number | undefined;
  // cutting_coefficient (Ф5а.2) is THE one visible, editable dial per article, replacing eight named
  // losses nobody can measure separately. It covers, together: усадка, обход пороков, сращивание,
  // оттеночные полосы — the roll-level reality a marker cannot contain, because a marker is measured
  // on a clean lay of a nominal width. A MULTIPLIER, not a percent (1.03 = +3%); accepted range
  // [1, 3].
  // Unset means nobody has set one and the requirement path multiplies by nothing — an article
  // without a coefficient plans exactly as it did before this field existed. There is deliberately
  // ONE default and no per-«класс ткани» taxonomy to pick it from; the value ranges (полотно ~3%,
  // трикотаж ~6%, клетка/полоска +10–20%) and what the coefficient covers belong in the field's hint
  // text, so nobody starts adding a column per loss again a year from now.
  // WRITE SEMANTICS — three states, not two, because "the client did not send the field" and "the
  // operator cleared it" must not be the same request (same rule as TechCardBomItem.purpose /
  // is_sample):
  // * field ABSENT (null)        → LEAVE AS IS. A stale admin tab, or any bundle from before this
  // field shipped, sends nothing and must not erase a coefficient an
  // operator set — silently, with no digest and no audit trail.
  // * field PRESENT, value ""    → CLEAR it (store NULL). This is how the UI unsets the dial.
  // * field PRESENT with a value → set it.
  // SCOPE — this is a DEMAND-side dial only. It grosses up the material PLAN's requirement
  // (GetProductionRunMaterialPlan) and nothing else: the run's planned unit cost and the style cost
  // estimate gross up by the BOM wastage % alone and do NOT include this coefficient. Planned COGS is
  // therefore understated by exactly the coefficient wherever one is set. That is deliberate for now —
  // moving it into the costing chain changes how product.cost_price is derived and every style's
  // margin with it, which is a separate, deliberately reviewed decision. Do not present a planned cost
  // as coefficient-inclusive.
  cuttingCoefficient: googletype_Decimal | undefined;
  // READ-ONLY (Ф5а.3): the vocabulary normalisation of `unit`. Ignored on write — set `unit`.
  // UNKNOWN = the free text does not map to any known unit, and must not be read as "no unit".
  unitCode: common_MaterialUnit | undefined;
  // fabric_thickness_mm (Ф4.8) — толщина полотна В ОДИН СЛОЙ, in MILLIMETRES. The article-side half
  // of the предел стопки: stack_height_cm = Σ plies × fabric_thickness_mm / 10, checked against the
  // workshop's WorkshopSettings.max_stack_height_cm. Ranges are a hint, not a taxonomy: шифон
  // 0.1-0.2, поплин ~0.3, драп 1.5-2.5. Accepted band (0, 50].
  // ABSENT MEANS «НЕ ЗАМЕРЕНО», AND THAT IS NOT ZERO. A нулевая толщина would make every lay
  // 0 cm tall and therefore "fits" — a confident verdict built on nothing, which is precisely the
  // failure «нет толщины — нет проверки, не догадка» forbids. A consumer with no thickness must
  // report UNKNOWN and withhold the height entirely, prompting «толщина ткани не задана на артикуле
  // — замерьте, и высота стопки начнёт проверяться». There is deliberately no default «по классу
  // ткани»: that taxonomy does not exist and inventing one to feed a guess is the disease this
  // avoids (same argument as cutting_coefficient above).
  // WRITE SEMANTICS — three states, verbatim the same as cutting_coefficient, its neighbour on the
  // article, and for the same reason (a stale admin tab, or any bundle from the window between the
  // backend and client deploys, sends nothing and must not erase a measurement somebody took with
  // calipers — silently, on a catalogue with neither a signed digest nor an edit journal):
  // * field ABSENT (null)        → LEAVE AS IS.
  // * field PRESENT, value ""    → CLEAR it (store NULL).
  // * field PRESENT with a value → set it.
  fabricThicknessMm: googletype_Decimal | undefined;
};

